# A message that asks to draw, model or look inside something, whatever the thing.
INTENT = re.compile(r"\b(draw|3-?d|model|show me|look like|looks like|inside|built|build|parts? of|cut.?away|"
                    r"cross.section|how (?:does|do|is|are) .{1,40} (?:work|built|made)|picture|illustrate|diagram)\b", re.I)


def family_for(task: str) -> Family | None:
    """The family whose words occur most in the message; a tie goes to the one with the longer
    matched words ("jet engine" is an engine, not a jet), then to the earlier family. None if no word hits."""
    best, best_score = None, (0, 0)
    for f in FAMILIES:
        found = re.findall(rf"\b(?:{f.words})\b", task, re.I)
        score = (len(found), sum(len(w) for w in found))
        if score > best_score:
            best, best_score = f, score
    return best


def guide_for(task: str) -> str:
    """The recipe, and the nearest family's example, for a message that asks to draw something;
    nothing for any other message (so ordinary turns pay nothing)."""
    if os.environ.get("BENJI_FIGURE_GUIDE", "").strip() == "0":   # off: the eval's baseline
        return ""
    family = family_for(task)
    if family is None and not INTENT.search(task):
        return ""
    if family is None:
        return RECIPE
    return (RECIPE + f"An example from the nearest family, which shows {family.shows}. Learn how it is built;\n"
            "build the user's thing from scratch at its own proportions, never copy this one:\n"
            "```figure\n" + family.example + "\n```\n")
